<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useFitness, withExerciseImage, DEFAULT_EXERCISE_IMAGE } from './store'
import ExerciseImage from './ExerciseImage.vue'
import { clone, type Exercise } from '../../../shared/fitness'
import AppIcon from '../components/AppIcon.vue'
const fs=useFitness(),route=useRoute(),query=ref(String(route.query.q||'')),part=ref('背'),equipment=ref('全部'),editingMuscles=ref(false),favorites=ref(false),page=ref(1),draft=ref<Exercise>(clone(fs.availableExercises.find(e=>e.id==='Wide-Grip_Lat_Pulldown')||fs.availableExercises[0])),imageIndex=ref(0)
const readyOrder=['Wide-Grip_Lat_Pulldown','Seated_Cable_Rows','One-Arm_Dumbbell_Row','Pullups','Straight-Arm_Pulldown','Dumbbell_Incline_Row']
const parts=['全部','胸','背','肩','腿','臀','手臂','核心','有氧'],equipments=['全部','哑铃','杠铃','固定器械','自重','绳索','壶铃','弹力带']
const filtered=computed(()=>fs.availableExercises.filter(e=>(part.value==='全部'||e.part===part.value)&&(equipment.value==='全部'||e.equipment===equipment.value)&&(!favorites.value||e.favorite)&&(e.name+e.alias+(e.sourceName||'')+e.description+e.tags.join(' ')).toLowerCase().includes(query.value.toLowerCase())).sort((a,b)=>(readyOrder.indexOf(a.id)<0?999:readyOrder.indexOf(a.id))-(readyOrder.indexOf(b.id)<0?999:readyOrder.indexOf(b.id))))
const visible=computed(()=>filtered.value.slice((page.value-1)*6,page.value*6))
watch([query,part,equipment,favorites],()=>page.value=1)
watch(()=>route.query.q,q=>{query.value=String(q||'');if(q)part.value='全部'})
function select(e:Exercise):void {draft.value=clone(e);imageIndex.value=0}
async function favorite(e:Exercise):Promise<void>{const v=clone(e);v.favorite=!v.favorite;fs.editExercise(v);if(draft.value.id===e.id)draft.value.favorite=v.favorite;await fs.save()}
function create():void{draft.value={id:crypto.randomUUID(),name:'新动作',alias:'',part:'自定义',muscles:[],secondary:[],equipment:'自重',measure:'weight',description:'',notes:'',image:DEFAULT_EXERCISE_IMAGE,images:[DEFAULT_EXERCISE_IMAGE],favorite:false,tags:[],artworkStatus:'ready'}}
async function save():Promise<void>{if(!draft.value.name.trim())return;draft.value.description=draft.value.muscles.length?'主要锻炼：'+draft.value.muscles.join('、')+'。'+(draft.value.secondary.length?'辅助参与：'+draft.value.secondary.join('、')+'。':''):'';draft.value=withExerciseImage(draft.value);fs.editExercise(draft.value);await fs.save('动作已保存')}
function upload(event:Event):void{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{draft.value.image=String(reader.result);draft.value.images=[draft.value.image];imageIndex.value=0};reader.readAsDataURL(file)}
const linked=computed(()=>fs.data.templates.filter(t=>t.items.some(i=>i.exerciseId===draft.value.id)))
defineExpose({create})
</script>
<template>
 <div class="fit-library-tools fit-card"><div class="fit-library-search" v-if="query"><AppIcon name="search" :size="16"/><input v-model="query" placeholder="搜索动作名称、肌肉或标签"/><button class="fit-icon" @click="query=''">×</button></div><div class="fit-library-filter-row"><div class="fit-filter-chips"><span>部位：</span><button v-for="p in parts" :key="p" :class="{active:part===p}" @click="part=p">{{ p }}</button></div><i class="fit-filter-divider"/><div class="fit-filter-chips equipment"><span>器械：</span><button v-for="e in equipments.slice(0,5)" :key="e" :class="{active:equipment===e}" @click="equipment=e">{{ e }}</button></div><button class="fit-button fit-favorite-filter" :class="{active:favorites}" @click="favorites=!favorites">☆ 收藏</button></div></div>
 <div class="fit-library-columns"><div class="fit-library-results"><div class="fit-exercise-grid"><button class="fit-exercise-card fit-card" :class="{selected:draft.id===e.id}" v-for="e in visible" :key="e.id" @click="select(e)"><div class="fit-exercise-picture"><ExerciseImage :image="e.image" loading="lazy" :alt="e.name"/></div><div class="fit-exercise-copy"><header><h3>{{ e.name }}</h3><span role="button" tabindex="0" class="fit-favorite" :class="{on:e.favorite}" @click.stop="favorite(e)" @keydown.enter.stop="favorite(e)">{{ e.favorite?'★':'☆' }}</span></header><div class="fit-tags"><span>{{ e.part }}部</span><span>{{ e.equipment }}</span></div><p>{{ e.description }}</p><footer><strong>{{ e.measure==='weight'?'次数 × 重量':e.measure==='time'?'时长':'距离' }}</strong><span>···</span></footer></div></button></div><p v-if="!visible.length" class="fit-empty fit-card">没有符合筛选条件的动作。</p><button class="fit-add-custom" @click="create"><AppIcon name="plus" :size="18"/>添加自定义动作</button><div class="fit-pagination"><span>共 {{ filtered.length }} 个动作</span><button @click="page=Math.max(1,page-1)" :disabled="page===1">‹</button><button class="active">{{ page }}</button><button @click="page++" :disabled="page*6>=filtered.length">›</button></div></div>
 <section class="fit-card fit-exercise-detail"><header><h2><AppIcon name="fitness"/>动作详情</h2><button class="fit-button" @click="editingMuscles=!editingMuscles;($refs.nameInput as HTMLInputElement).focus()"><AppIcon name="edit" :size="15"/>编辑</button></header>
  <div class="fit-detail-top"><div class="fit-detail-image"><ExerciseImage :image="draft.images[imageIndex]||draft.image" :alt="draft.name"/><label class="fit-image-change"><AppIcon name="upload" :size="13"/>更换图片<input type="file" accept="image/*" @change="upload"/></label></div><div class="fit-detail-identity"><label>动作名称 <b>*</b><input ref="nameInput" v-model="draft.name"/></label><label>别名<input v-model="draft.alias" placeholder="例如：下拉、宽握高位下拉"/></label><div class="fit-identity-pair"><label>主要部位 <b>*</b><select v-model="draft.part"><option v-for="p in [...parts.slice(1),'自定义']">{{ p }}</option></select></label><label>器械 <b>*</b><select v-model="draft.equipment"><option v-for="e in equipments.slice(1)">{{ e }}</option></select></label></div></div></div>
  <label class="fit-label fit-measure-label">计量方式 <b>*</b><div class="fit-segment"><button v-for="[value,label] in [['weight','次数 × 重量'],['time','时长'],['distance','距离']]" :class="{active:draft.measure===value}" @click="draft.measure=value as Exercise['measure']">{{ label }}</button></div></label><label class="fit-label">自定义标签<div class="fit-tags"><span v-for="(t,i) in draft.tags" @click="draft.tags.splice(i,1)">{{ t }} ×</span><input class="fit-tag-add" placeholder="＋ 添加标签" @keydown.enter.prevent="draft.tags.push(($event.target as HTMLInputElement).value);($event.target as HTMLInputElement).value=''"/></div></label><label class="fit-label fit-note-label">我的动作笔记<textarea v-model="draft.notes" :placeholder="draft.description" rows="3"/></label><details v-if="editingMuscles" open class="fit-muscle-fields"><summary>目标肌肉 · {{ draft.muscles.join('、') }}</summary><label class="fit-label">主要肌肉<input :value="draft.muscles.join('、')" @input="draft.muscles=($event.target as HTMLInputElement).value.split('、')"/></label><label class="fit-label">辅助肌肉<input :value="draft.secondary.join('、')" @input="draft.secondary=($event.target as HTMLInputElement).value.split('、').filter(Boolean)"/></label></details>
  <label class="fit-label">自定义图片<div class="fit-custom-images"><ExerciseImage :image="draft.image" alt="当前动作卡通图"/><label class="fit-upload"><AppIcon name="plus" :size="18"/><span>上传图片</span><input type="file" accept="image/*" @change="upload"/></label><small>图片选填，未上传时自动使用默认卡通图。支持 JPG、PNG。</small></div></label><div class="fit-related-template"><span>▱ 已用于 {{ linked.length }} 个模板</span><span :title="linked.map(t=>t.title).join('、')">关联模板 ›</span></div><footer class="fit-detail-footer"><small>ⓘ 默认值可在各训练计划里单独调整。</small><button class="fit-primary" @click="save">保存动作</button></footer>
 </section></div>
</template>
